<?php
require_once 'functions.php';require_role(['pelanggan']);$uid=(int)user()['id_user'];$cart=active_cart($pdo,$uid);
$s=$pdo->prepare("SELECT d.*,p.nama_produk,p.stok,p.jenis_produk FROM tbl_detail_keranjang d JOIN tbl_produk p ON p.id_produk=d.id_produk JOIN tbl_keranjang k ON k.id_keranjang=d.id_keranjang WHERE k.id_keranjang=?");$s->execute([$cart]);$items=$s->fetchAll();if(!$items)go('keranjang.php');$subtotal=array_sum(array_column($items,'subtotal'));$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$code=trim($_POST['voucher']??'');$discount=0;$voucher=null;
 if($code!==''){$v=$pdo->prepare("SELECT * FROM tbl_diskon WHERE kode_diskon=? AND status='aktif' AND CURDATE() BETWEEN tanggal_mulai AND tanggal_selesai");$v->execute([$code]);$voucher=$v->fetch();if(!$voucher)$error='Kode voucher tidak valid atau tidak aktif.';elseif($subtotal<(float)$voucher['minimal_belanja'])$error='Belanja belum mencapai minimal voucher.';else{$discount=$voucher['jenis_diskon']==='persen'?$subtotal*(float)$voucher['nilai_diskon']/100:(float)$voucher['nilai_diskon'];if($voucher['maksimal_potongan']!==null)$discount=min($discount,(float)$voucher['maksimal_potongan']);$discount=min($discount,$subtotal);}}
 if(!$error){try{$pdo->beginTransaction();foreach($items as $it){if($it['jenis_produk']==='barang' && (int)$it['stok']<(int)$it['jumlah'])throw new Exception('Stok '.$it['nama_produk'].' tidak mencukupi.');}
 $pid=ensure_customer($pdo,$uid,user()['nama']);$no='ORD-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$total=$subtotal-$discount;
 $pdo->prepare("INSERT INTO tbl_transaksi(tanggal,id_pelanggan,total_belanja,nomor_transaksi,id_user,subtotal,diskon,total_bayar,status,catatan) VALUES(CURDATE(),?,?,?,?,?,?,?,'menunggu',?)")->execute([$pid,$subtotal,$no,null,$subtotal,$discount,$total,'Pesanan online '.$no]);
 $tid=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE tbl_transaksi SET nomor_transaksi=? WHERE id_transaksi=?")->execute([$no,$tid]);
 foreach($items as $it){$pdo->prepare("INSERT INTO tbl_detail_transaksi(id_transaksi,id_produk,nama_produk,harga,jumlah,subtotal) VALUES(?,?,?,?,?,?)")->execute([$tid,$it['id_produk'],$it['nama_produk'],$it['harga'],$it['jumlah'],$it['subtotal']]);}
 if($voucher)$pdo->prepare("UPDATE tbl_transaksi SET catatan=? WHERE id_transaksi=?")->execute(['Voucher '.$code,$tid]);
 $pdo->prepare("UPDATE tbl_keranjang SET status='checkout' WHERE id_keranjang=?")->execute([$cart]);$pdo->commit();$pdo->prepare("INSERT INTO tbl_notifikasi(id_user,judul,pesan) VALUES(?,?,?)")->execute([$uid,'Pesanan diterima','Pesanan '.$no.' menunggu diproses kasir.']);flash('Checkout berhasil. Pesanan menunggu diproses kasir.');go('pesanan_saya.php');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
}
layout_header('Checkout');
?>
<div class="page-title"><div><span class="eyebrow">SATU LANGKAH LAGI</span><h1>Checkout pesanan</h1><p>Pesanan akan diteruskan ke kasir untuk pembayaran.</p></div></div><div class="cart-layout"><section class="panel"><h3>Rincian pesanan</h3><?php foreach($items as $it):?><div class="summary-row"><span><?=e($it['nama_produk'])?> × <?=$it['jumlah']?></span><b><?=rupiah($it['subtotal'])?></b></div><?php endforeach;?><hr><div class="summary-row"><span>Subtotal</span><b><?=rupiah($subtotal)?></b></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Kode voucher (opsional)</label><input name="voucher" placeholder="Contoh: HEMAT10"><button class="btn btn-primary">Buat Pesanan</button></form><?php if($error):?><div class="flash flash-error"><?=e($error)?></div><?php endif;?></section><aside class="panel summary"><h3>Total sementara</h3><div class="summary-total"><span>Subtotal</span><strong><?=rupiah($subtotal)?></strong></div><p class="muted small">Diskon voucher akan dihitung saat pesanan dibuat. Pembayaran dilakukan melalui kasir.</p></aside></div>
<?php layout_footer(); ?>
